public class UpdateVisitor : Visitor
{
    public void VisitComputer(Computer computer)
    {
        computer.Traverse(this);
    }

    public void VisitHardware(Hardware hardware)
    {
        hardware.Update();
        foreach (Hardware subhardware in hardware.Subhardware)
            subhardware.Accept(this);
    }

    public void VisitSensor(ISensor sensor)
    {
        Console.WriteLine("Sensor: {0}", sensor.Name);
        Console.WriteLine("Value: {0}", sensor.Value);
    }

    public void VisitParameter(IParameter parameter)
    {
        Console.WriteLine("Parameter: {0}", parameter.Name);
        Console.WriteLine("Value: {0}", parameter.Value);
    }

    public void Monitor()
    {
        Computer computer = new Computer();

        isCpuEnabled = true;
        isGpuEnabled = true;
        isMemoryEnabled = true;
        isMotherboardEnabled = true;
        isStorageEnabled = true;

        computer.Open();
        computer.Accept(new UpdateVisitor());

        foreach (Hardware hardware in computer.Hardware)
        {
            Console.WriteLine("Hardware: {0}", hardware.Name);
            foreach (Hardware subhardware in hardware.Subhardware)
            {
                Console.WriteLine("  Subhardware: {0}", subhardware.Name);
                foreach (ISensor sensor in subhardware.Sensors)
                {
                    Console.WriteLine("    Sensor: {0}, value: {1}", sensor.Name, sensor.Value);
                }
            }
        }

        foreach (ISensor sensor in computer.Sensors)
        {
            Console.WriteLine("Sensor: {0}, value: {1}", sensor.Name, sensor.Value);
        }

        computer.Close();
    }
}
